    /** Constructors from a stub of the stub-based implementations, by element type (every kind of their classes). */
    @JvmField val stubConstructors: Map<IElementType, (CSharpStub, IElementType) -> PsiElement> = createStubbed()

    private fun createStubbed(): Map<IElementType, (CSharpStub, IElementType) -> PsiElement> {
        val map = HashMap<IElementType, (CSharpStub, IElementType) -> PsiElement>(64)
        for (k in arrayOf(K.VariableDeclaration)) map[k] = { stub, type -> CSharpVariableDeclarationImpl(stub, type) }
        for (k in arrayOf(K.VariableDeclarator)) map[k] = { stub, type -> CSharpVariableDeclaratorImpl(stub, type) }
        for (k in arrayOf(K.CompilationUnit)) map[k] = { stub, type -> CSharpCompilationUnitImpl(stub, type) }
        for (k in arrayOf(K.NamespaceDeclaration)) map[k] = { stub, type -> CSharpNamespaceDeclarationImpl(stub, type) }
        for (k in arrayOf(K.FileScopedNamespaceDeclaration)) map[k] = { stub, type -> CSharpFileScopedNamespaceDeclarationImpl(stub, type) }
        for (k in arrayOf(K.ClassDeclaration)) map[k] = { stub, type -> CSharpClassDeclarationImpl(stub, type) }
        for (k in arrayOf(K.StructDeclaration)) map[k] = { stub, type -> CSharpStructDeclarationImpl(stub, type) }
        for (k in arrayOf(K.InterfaceDeclaration)) map[k] = { stub, type -> CSharpInterfaceDeclarationImpl(stub, type) }
        for (k in arrayOf(K.RecordDeclaration, K.RecordStructDeclaration)) map[k] = { stub, type -> CSharpRecordDeclarationImpl(stub, type) }
